  }
  .task-fading-in {
    animation: task-fade-through-in 292ms cubic-bezier(0.2, 0, 0, 1) both;
  }
  .symbol {
    font-weight: 700;
    text-decoration: underline;
    color: ${cta};
    cursor: pointer;
  }

  .preview-section {
    margin-top: 16px;
    padding: 0;
    position: relative;
  }
  .preview-label {
    font-family: "JetBrains Mono", monospace;
    font-size: 12px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 1px;
    color: ${colors.onSurfaceVariant};
    margin-bottom: 8px;
  }
  .preview-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 8px;
    padding: 0 16px;
  }
  .maximize-btn {
    background: ${colors.surfaceContainerHigh};
